/** Loopback test fixture only. Never part of any production archive. */
public final class NetworkProbe extends JavaPlugin {
 private final Gson json=new Gson();private JavaPlugin social,islands,arena,battle,vampir;
 public void onEnable(){if(!Bukkit.getIp().equals("127.0.0.1"))throw new IllegalStateException("Loopback only");social=(JavaPlugin)Bukkit.getPluginManager().getPlugin("KasabaSosyal");islands=(JavaPlugin)Bukkit.getPluginManager().getPlugin("KasabaAdalar");arena=(JavaPlugin)Bukkit.getPluginManager().getPlugin("KasabaArena");battle=(JavaPlugin)Bukkit.getPluginManager().getPlugin("BattleRoyalePrototype");vampir=(JavaPlugin)Bukkit.getPluginManager().getPlugin("KasabaVampirKoylu");Bukkit.getMessenger().registerIncomingPluginChannel(this,"kasaba_test:network",(channel,p,bytes)->{if(bytes.length>2048||p.getAddress()==null||!p.getAddress().getAddress().isLoopbackAddress())return;String op=new String(bytes,StandardCharsets.UTF_8);String[] a=op.split("\\|",-1);try{switch(a[0]){
  case "CMD"->{PlayerCommandPreprocessEvent e=new PlayerCommandPreprocessEvent(p,"/"+a[1]);Bukkit.getPluginManager().callEvent(e);if(!e.isCancelled())Bukkit.dispatchCommand(p,a[1]);}
  case "CONSOLE"->Bukkit.dispatchCommand(Bukkit.getConsoleSender(),a[1]);
  case "STATE"->state(p);
  case "ADMIN"->p.setOp(true);
  case "USER"->p.setOp(false);
  case "ITEM"->p.getInventory().setItem(Integer.parseInt(a[1]),new ItemStack(Material.valueOf(a[2]),Integer.parseInt(a[3])));
  case "FREEZE"->{p.setGravity(false);p.setVelocity(new org.bukkit.util.Vector());}
  case "TOOL"->{org.bukkit.NamespacedKey key=new NamespacedKey(social,"lobi-araci");ItemStack item=Arrays.stream(p.getInventory().getContents()).filter(Objects::nonNull).filter(i->i.hasItemMeta()&&i.getItemMeta().getPersistentDataContainer().getOrDefault(key,org.bukkit.persistence.PersistentDataType.INTEGER,-1)==Integer.parseInt(a[1])).findFirst().orElseThrow();Bukkit.getPluginManager().callEvent(new PlayerInteractEvent(p,org.bukkit.event.block.Action.RIGHT_CLICK_AIR,item,null,org.bukkit.block.BlockFace.UP,EquipmentSlot.HAND));}
  case "CANSEE"->{Player target=Bukkit.getPlayerExact(a[1]);say(p,"visible:"+p.canSee(target));}
  case "ACTIVITY"->{((Map<UUID,Long>)field(social,"activity")).put(p.getUniqueId(),Long.parseLong(a[1]));((Map<UUID,Long>)field(social,"actions")).put(p.getUniqueId(),System.currentTimeMillis()-Long.parseLong(a[2]));}
  case "FISH"->{for(int i=0;i<Integer.parseInt(a[1]);i++){Item item=p.getWorld().dropItem(p.getLocation(),new ItemStack(Material.COD));PlayerFishEvent event=new PlayerFishEvent(p,item,null,PlayerFishEvent.State.CAUGHT_FISH);Bukkit.getPluginManager().callEvent(event);if(event.isCancelled()){item.remove();throw new IllegalStateException("Fish cancelled");}ItemStack caught=item.getItemStack().clone();item.remove();if(!p.getInventory().addItem(caught).isEmpty())throw new IllegalStateException("Inventory full");}}
  case "COPY_FISH"->{Player target=Bukkit.getPlayerExact(a[1]);ItemStack item=Arrays.stream(p.getInventory().getContents()).filter(Objects::nonNull).filter(i->i.hasItemMeta()&&i.getItemMeta().getPersistentDataContainer().has(new NamespacedKey(social,"tutulan-balik"))).findFirst().orElseThrow();target.getInventory().addItem(item.clone());}
  case "FISH_CLOCK"->{String key="players."+p.getUniqueId()+".fishing."+a[1];edit(y->y.set(key,Long.parseLong(a[2])));}
  case "VIP"->Bukkit.getServicesManager().load(RoleAccess.class).grantVip(p.getUniqueId(),System.currentTimeMillis()+Long.parseLong(a[1]));
  case "EXPIRE_VIP"->{JavaPlugin roles=(JavaPlugin)Bukkit.getPluginManager().getPlugin("KasabaRoles");Object terms=field(roles,"vipTerms");((Map<UUID,Long>)field(terms,"terms")).put(p.getUniqueId(),System.currentTimeMillis()-1);call(roles,"applyAll");}
  case "ABS"->p.setAbsorptionAmount(Double.parseDouble(a[1]));
  case "BR_DAMAGE_AGE"->{Object room=call(battle,"room",p);((Map<UUID,Long>)field(room,"lastHitAt")).put(p.getUniqueId(),System.currentTimeMillis()-Long.parseLong(a[1]));}
  case "BR_CONSUME"->{ItemStack item=(ItemStack)call(field(battle,"loot"),"reserve",Integer.parseInt(a[1]),1);PlayerItemConsumeEvent e=new PlayerItemConsumeEvent(p,item,EquipmentSlot.HAND);Bukkit.getPluginManager().callEvent(e);say(p,"consume:"+e.isCancelled());}
  case "BR_DROP"->{Object room=call(battle,"room",p);ItemStack item=new ItemStack(Material.valueOf(a[1]),Integer.parseInt(a[2]));call(battle,"tag",item,room);Item entity=p.getWorld().dropItem(p.getLocation(),item);entity.setPickupDelay(0);entity.setGravity(false);entity.setVelocity(new org.bukkit.util.Vector());}
  case "BR_CLICK"->{int slot=Integer.parseInt(a[1]);boolean shift=Boolean.parseBoolean(a[2]);InventoryClickEvent e=new InventoryClickEvent(p.getOpenInventory(),InventoryType.SlotType.CONTAINER,slot,shift?ClickType.SHIFT_LEFT:ClickType.LEFT,shift?InventoryAction.MOVE_TO_OTHER_INVENTORY:InventoryAction.PICKUP_ALL);Bukkit.getPluginManager().callEvent(e);say(p,"cancelled:"+e.isCancelled());}
  case "BR_SHIFT"->{Inventory top=p.getOpenInventory().getTopInventory();int slot=top.firstEmpty();for(int i=0;i<top.getSize();i++)if(top.getItem(i)!=null){slot=i;break;}InventoryClickEvent e=new InventoryClickEvent(p.getOpenInventory(),InventoryType.SlotType.CONTAINER,slot,ClickType.SHIFT_LEFT,InventoryAction.MOVE_TO_OTHER_INVENTORY);Bukkit.getPluginManager().callEvent(e);say(p,"cancelled:"+e.isCancelled());}
  case "BR_DRAG"->{int raw=Integer.parseInt(a[1]);InventoryDragEvent e=new InventoryDragEvent(p.getOpenInventory(),new ItemStack(Material.STONE),new ItemStack(Material.STONE,2),false,Map.of(raw,new ItemStack(Material.STONE)));Bukkit.getPluginManager().callEvent(e);say(p,"cancelled:"+e.isCancelled());}
  case "BR_SWAP"->{PlayerSwapHandItemsEvent e=new PlayerSwapHandItemsEvent(p,p.getInventory().getItemInOffHand(),p.getInventory().getItemInMainHand());Bukkit.getPluginManager().callEvent(e);say(p,"cancelled:"+e.isCancelled());}
  case "SAFETY"->{PlayerInteractEvent e=new PlayerInteractEvent(p,org.bukkit.event.block.Action.RIGHT_CLICK_AIR,new ItemStack(Material.valueOf(a[1])),null,org.bukkit.block.BlockFace.UP,EquipmentSlot.HAND);Bukkit.getPluginManager().callEvent(e);say(p,"use:"+e.useItemInHand());}
  case "LAND"->{Object room=call(battle,"room",p);Object d=call(battle,"definition",(int)field(room,"id"));List<Location> spawns=(List<Location>)field(d,"spawns");call(battle,"teleport",p,spawns.getFirst());p.setGravity(false);}
  case "CLAIM_MARK"->{int id=Integer.parseInt(a[1]);Object layout=field(islands,"layout");int x=(int)call(layout,"centerX",id),z=(int)call(layout,"centerZ",id);World w=Bukkit.getWorld("ada");w.getBlockAt(x,110,z).setType(Material.DIAMOND_BLOCK);w.getBlockAt(x,w.getMinHeight()+2,z).setType(Material.AIR);w.getBlockAt(x+1,110,z).setType(Material.CHEST);((org.bukkit.block.Chest)w.getBlockAt(x+1,110,z).getState()).getBlockInventory().addItem(new ItemStack(Material.DIAMOND,64));}
  case "EXPIRE_ISLANDS"->{UUID id=Bukkit.getOfflinePlayer(a[1]).getUniqueId();Object claims=field(islands,"claims");call(claims,"seen",id,System.currentTimeMillis()-15L*86400000-1000);call(field(islands,"resetter"),"sweep");}
  case "PAUSE_FOR_RESTART"->{Bukkit.getScheduler().cancelTasks(islands);Bukkit.getScheduler().cancelTasks(social);edit(y->{var credits=y.getConfigurationSection("credits");if(credits!=null)for(String id:credits.getKeys(false))y.set("credits."+id+".pending",true);var purchases=y.getConfigurationSection("purchases");if(purchases!=null)for(String id:purchases.getKeys(false))if(y.getBoolean("purchases."+id+".success"))y.set("purchases."+id+".pending",true);});}
  case "RESET"->{Object claims=field(islands,"claims"),resetter=field(islands,"resetter"),job=field(resetter,"job"),layout=field(islands,"layout");int id=Integer.parseInt(a[1]),x=(int)call(layout,"centerX",id),z=(int)call(layout,"centerZ",id);World w=Bukkit.getWorld("ada");Map<String,Object> info=new LinkedHashMap<>();info.put("owner",call(claims,"ownerOf",id));info.put("resetting",call(claims,"resetting",id));info.put("job",job==null?0:field(job,"id"));info.put("cursor",job==null?0:field(job,"cursor"));info.put("marker",w.getBlockAt(x,110,z).getType().name());info.put("chest",w.getBlockAt(x+1,110,z).getType().name());info.put("deep",w.getBlockAt(x,w.getMinHeight()+2,z).getType().name());say(p,"reset:"+json.toJson(info));}
  default->throw new IllegalArgumentException("Unknown fixture operation");}say(p,"done:"+op);}catch(Throwable e){say(p,"error:"+e);getLogger().log(java.util.logging.Level.SEVERE,"Fixture failed",e);}});}
 private Object field(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
 private Object call(Object target,String name,Object... args)throws Exception{Method method=Arrays.stream(target.getClass().getDeclaredMethods()).filter(m->m.getName().equals(name)&&m.getParameterCount()==args.length).filter(m->{Class<?>[] types=m.getParameterTypes();for(int i=0;i<types.length;i++)if(args[i]!=null&&!types[i].isPrimitive()&&!types[i].isInstance(args[i]))return false;return true;}).findFirst().orElseThrow();method.setAccessible(true);return method.invoke(target,args);}
 private void edit(Consumer<YamlConfiguration> change)throws Exception{call(field(social,"data"),"update",change);}
 private void state(Player p)throws Exception{UUID id=p.getUniqueId();HubApi hub=Bukkit.getServicesManager().load(HubApi.class);RoleAccess roles=Bukkit.getServicesManager().load(RoleAccess.class);Map<String,Object> d=new LinkedHashMap<>();d.put("uuid",id.toString());d.put("entity",p.getEntityId());d.put("world",p.getWorld().getName());d.put("mode",p.getGameMode().name());d.put("social",hub.socialArea(id));d.put("gameplay",hub.gameplay(id));d.put("main",hub.mainLobby(id));d.put("vip",roles.vip(p));d.put("until",roles.vipUntil(id));d.put("balance",Bukkit.getServicesManager().load(AkceApi.class).balance(id).toPlainString());d.put("flight",p.getAllowFlight());d.put("absorption",p.getAbsorptionAmount());d.put("hp",p.getHealth());d.put("x",p.getX());d.put("y",p.getY());d.put("z",p.getZ());d.put("items",Arrays.stream(p.getInventory().getContents()).map(item->item==null?"AIR":item.getType()+":"+item.getAmount()).toList());d.put("armor",Arrays.stream(p.getInventory().getArmorContents()).map(item->item==null?"AIR":item.getType()+":"+item.getEnchantmentLevel(org.bukkit.enchantments.Enchantment.PROTECTION)).toList());d.put("owned",call(field(islands,"claims"),"owned",id));d.put("place",String.valueOf(((Map<?,?>)field(arena,"places")).get(id)));d.put("cooldowns",((Map<?,?>)field(field(arena,"combat"),"cooldowns")).get(id));Object room=call(battle,"room",p);d.put("br",room==null?null:Map.of("id",field(room,"id"),"stage",field(room,"stage").toString(),"chests",((Map<?,?>)field(room,"chests")).size()));Object vk=((Map<?,?>)field(vampir,"membership")).get(id);d.put("vk",vk==null?null:Map.of("id",field(vk,"id"),"phase",field(vk,"phase").toString(),"role",String.valueOf(((Map<?,?>)field(vk,"roles")).get(id))));YamlConfiguration data=(YamlConfiguration)call(field(social,"data"),"get");String k="players."+id+".fishing";d.put("fishSold",data.getInt(k+".sold"));d.put("fishUntil",data.getLong(k+".until"));d.put("rodAt",data.getLong(k+".rodAt"));say(p,"state:"+json.toJson(d));}
 private void say(Player p,String text){p.sendMessage(net.kyori.adventure.text.Component.text("network-probe:"+text));}
}
